-- Văn bản gửi xã (số CV-năm-xxx), 4 mẫu văn bản, thiết lập nhắc gọi lại cho owner.
-- Chạy lại an toàn.
begin;

alter table public.sales_docs drop constraint if exists sales_docs_kind_check;
alter table public.sales_docs add constraint sales_docs_kind_check check (kind in ('quote','contract','letter'));
alter table public.sales_templates drop constraint if exists sales_templates_kind_check;
alter table public.sales_templates add constraint sales_templates_kind_check check (kind in ('quote','contract','letter'));

create or replace function public.sales_doc_review(p_id uuid, p_ok boolean, p_note text default null) returns text
language plpgsql security definer set search_path = public as $$
declare d public.sales_docs; n text; pre text; yr text := to_char(now() at time zone 'Asia/Ho_Chi_Minh', 'YYYY'); k int;
begin
  if not sales_mgr() then raise exception 'not_manager'; end if;
  select * into d from sales_docs where id = p_id for update;
  if not found then raise exception 'not_found'; end if;
  if d.status not in ('pending','draft') then raise exception 'bad_status'; end if;
  perform set_config('sales.doc_rpc', '1', true);
  if not p_ok then
    update sales_docs set status = 'rejected', reviewed_by = auth.uid(), reviewed_at = now(), review_note = nullif(trim(coalesce(p_note,'')),'') where id = p_id;
    perform set_config('sales.doc_rpc', '', true);
    return null;
  end if;
  n := d.number;
  if n is null then
    pre := case d.kind when 'contract' then 'HĐ' when 'letter' then 'CV' else 'BG' end || '-' || yr || '-';
    select coalesce(max(substring(number from length(pre) + 1)::int), 0) + 1 into k from sales_docs where number like pre || '%' and substring(number from length(pre) + 1) ~ '^\d+$';
    n := pre || lpad(k::text, 3, '0');
  end if;
  update sales_docs set status = 'approved', number = n, reviewed_by = auth.uid(), reviewed_at = now(), review_note = nullif(trim(coalesce(p_note,'')),''),
    company_snap = (select to_jsonb(c) - 'updated_by' from sales_companies c where c.id = d.company_id)
  where id = p_id;
  perform set_config('sales.doc_rpc', '', true);
  return n;
end $$;
revoke all on function public.sales_doc_review(uuid,boolean,text) from public, anon;
grant execute on function public.sales_doc_review(uuid,boolean,text) to authenticated;

-- Thiết lập chung của Sales (owner sửa, nhân sự Sales đọc)
create table if not exists public.sales_settings (
  key text primary key,
  value jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid()
);
alter table public.sales_settings enable row level security;
drop policy if exists ss_read on public.sales_settings;
create policy ss_read on public.sales_settings for select to authenticated using (sales_any());
drop policy if exists ss_write on public.sales_settings;
create policy ss_write on public.sales_settings for all to authenticated
  using (my_role() = 'owner' and is_active()) with check (my_role() = 'owner' and is_active());
grant select, insert, update, delete on public.sales_settings to authenticated;

-- Số ngày nhắc gọi lại mặc định (0 = không nhắc)
insert into public.sales_settings(key, value) values ('remind',
  '{"talked":5,"interested":5,"later":5,"sent":5,"noans":2,"unreach":3,"nofind":0,"wrong":0,"refused":0,"quote":5,"contract":5,"letter":5,"stage9":30}'::jsonb)
on conflict (key) do nothing;

insert into public.sales_templates(code,kind,name,description,company_id,body,sort) select 'tpl-cv-gioi-thieu','letter','Công văn giới thiệu BVI, đề xuất đồng hành TXNG và mã số vùng trồng','Gửi lần đầu cho UBND xã, phường. Có chi phí làm mã mới 15 tr + 5 tr.',(select id from public.sales_companies where code='bvi'),'{"title": "", "subtitle": "đề xuất phối hợp hỗ trợ bà con về truy xuất nguồn gốc, mã số vùng trồng trên địa bàn {{xa}}", "to": "<p><b>Kính gửi:</b></p><p>- Ủy ban nhân dân {{xa}};</p><p>- Phòng Kinh tế {{xa}}.</p>", "blocks": [{"t": "text", "h": "", "html": "<p>Thực hiện Nghị quyết số 36/2026/NQ-CP của Chính phủ về đơn giản hóa thủ tục hành chính liên quan đến mã số vùng trồng, mã số cơ sở đóng gói; Nghị định số 372/2026/NĐ-CP ngày 29/9/2026 của Chính phủ quy định về hoạt động định danh, xác thực, truy xuất nguồn gốc sản phẩm, hàng hóa (hiệu lực từ ngày 01/01/2027) và Kế hoạch truy xuất nguồn gốc nông sản của Bộ Nông nghiệp và Môi trường, {{cong_ty}} (sau đây gọi là {{cong_ty_ngan}}) kính đề xuất phối hợp cùng Quý cơ quan hỗ trợ bà con trên địa bàn như sau:</p>"}, {"t": "text", "h": "1. Những vấn đề thực tiễn địa phương đang gặp", "html": "<ul><li>Vùng trồng đã có mã: nhật ký canh tác chủ yếu ghi trên giấy, thiếu hồ sơ phân bón, thuốc bảo vệ thực vật, thu hoạch; khi hậu kiểm hoặc lô hàng bị cảnh báo, mã số vùng trồng có nguy cơ bị tạm dừng, thu hồi. Từ ngày 01/01/2027, dữ liệu truy xuất nguồn gốc cần được kết nối với hệ thống quốc gia.</li><li>Ủy ban nhân dân xã: theo Nghị quyết số 36/2026/NQ-CP, xã trực tiếp tiếp nhận, kiểm tra hồ sơ mã số vùng trồng trong 10 ngày làm việc và theo dõi việc duy trì mã sau cấp, nhưng chưa có công cụ nắm dữ liệu vùng trồng trên địa bàn.</li><li>Hộ dân chưa có mã: có nhu cầu nhưng chưa rõ điều kiện, hồ sơ, trình tự; chưa có tổ hợp tác, hợp tác xã đại diện đứng tên mã số vùng trồng nên dễ phụ thuộc, thiếu minh bạch.</li><li>Kỹ thuật và tổ chức sản xuất: bà con còn hạn chế về VietGAP, giám sát sinh vật gây hại (ISPM 6); nhiều hợp tác xã, tổ hợp tác quản lý chưa hiệu quả.</li></ul>"}, {"t": "text", "h": "2. Nội dung {{cong_ty_ngan}} đề xuất hỗ trợ", "html": "<p>a) Tổ chức 01 buổi đào tạo, tập huấn tại xã (thời gian, địa điểm do Quý cơ quan sắp xếp): truy xuất nguồn gốc, hậu kiểm và duy trì mã số vùng trồng; trình tự đăng ký mã số vùng trồng, thành lập tổ hợp tác; chuyên đề VietGAP, ISPM 6, quản lý hợp tác xã. {{cong_ty_ngan}} chuẩn bị nội dung, tài liệu, giảng viên.</p><p>b) Miễn phí 01 năm sử dụng nền tảng FarmBase cho các vùng trồng đã có mã số (không bao gồm chi phí thực địa phát sinh, nếu có): ghi nhật ký canh tác trên Zalo, không cần cài ứng dụng; đồng bộ dữ liệu với Hệ thống truy xuất nguồn gốc nông sản của Bộ Nông nghiệp và Môi trường.</p><p>c) Bàn giao miễn phí tài khoản quản lý cấp xã để Quý cơ quan theo dõi danh sách vùng trồng, tình hình ghi nhật ký và dữ liệu truy xuất trên địa bàn.</p><p>d) Đồng hành bà con làm mã số vùng trồng mới do tổ hợp tác, hợp tác xã đứng tên: hướng dẫn thành lập tổ hợp tác theo Nghị định số 77/2019/NĐ-CP (hoặc củng cố hợp tác xã sẵn có) để bà con chủ động đứng tên, quản lý mã; hỗ trợ hồ sơ theo Nghị quyết số 36/2026/NQ-CP từ mã nội địa đến khi được cấp mã xuất khẩu, với chi phí tối thiểu tại mục 3.</p><p>Chương trình áp dụng trước cho cây sầu riêng và có thể mở rộng cho cà phê, các cây trồng xuất khẩu chủ lực khác của xã.</p>"}, {"t": "text", "h": "3. Chi phí tối thiểu triển khai mã số vùng trồng cho bà con", "html": "<p>Tính cho một vùng trồng do tổ hợp tác, hợp tác xã của bà con đứng tên, từ khi lập hồ sơ đến khi được cấp mã; chỉ gồm các khoản thực tế phải chi, công khai trước khi triển khai:</p><ul><li>Đợt 1, khi triển khai: 15.000.000 đồng/vùng, gồm đi lại và công tác phí chuyên gia thực địa (03 ngày, vùng cách dưới 30 km), in ấn hồ sơ, chụp flycam, vật tư (bẫy côn trùng, biển thông tin vùng, bảo hộ), thù lao người đại diện vùng và hậu cần đợt kiểm tra thực địa;</li><li>Đợt 2, chỉ khi vùng được cấp mã: 5.000.000 đồng/vùng (phí hoàn thiện hồ sơ); vùng chưa được cấp mã không phải trả khoản này.</li></ul><p>Tổng khoảng 20.000.000 đồng/vùng, tương đương khoảng 2.000.000 đồng/ha với vùng 10 ha. Chưa gồm chi phí duy trì, hậu kiểm mã số vùng trồng hằng năm sau khi được cấp mã, lệ phí nhà nước và dịch vụ của bên thứ ba (nếu có). Ngày thực địa phát sinh tính thêm theo thực tế.</p><p>Nguồn kinh phí: bà con, tổ hợp tác tự chi trả; Quý cơ quan xem xét lồng ghép nguồn hợp pháp; hoặc doanh nghiệp thu mua cùng chia sẻ.</p>"}, {"t": "text", "h": "4. Năng lực của {{cong_ty_ngan}}", "html": "<p>{{cong_ty_ngan}} là đơn vị cung cấp giải pháp tích hợp với Hệ thống truy xuất nguồn gốc nông sản của Bộ Nông nghiệp và Môi trường; hội viên Hiệp hội Sầu riêng tỉnh Đắk Lắk. Nền tảng FarmBase do BVI và Salefronts đồng phát triển.</p>"}, {"t": "text", "h": "5. Kính đề nghị Quý cơ quan", "html": "<ul><li>Cử 01 cán bộ đầu mối phối hợp; cung cấp danh sách vùng trồng đã có mã số (mã nội địa, mã xuất khẩu) trên địa bàn; cho ý kiến về chi phí tại mục 3;</li><li>Chọn ngày tổ chức; thông báo, mời đại diện vùng trồng, hộ dân, hợp tác xã, tổ hợp tác, doanh nghiệp; bố trí hội trường, âm thanh, máy chiếu.</li></ul><p>Việc cấp, quản lý mã số vùng trồng thuộc thẩm quyền cơ quan quản lý nhà nước; {{cong_ty_ngan}} hỗ trợ kỹ thuật, hồ sơ và vận hành hệ thống, không cam kết thời gian cấp mã. Bà con tự nguyện tham gia, không phát sinh nghĩa vụ bắt buộc sử dụng dịch vụ của {{cong_ty_ngan}}; dữ liệu cá nhân được bảo mật theo Nghị định số 13/2023/NĐ-CP.</p><p>Đầu mối liên hệ: bà Ngọc, điện thoại/Zalo: {{dien_thoai}}; email: {{email}}. Cán bộ phụ trách: {{nguoi_lap}}. {{cong_ty_ngan}} kính đề nghị Quý cơ quan thông tin họ tên, chức vụ, số điện thoại cán bộ đầu mối để hai bên thống nhất kế hoạch chi tiết.</p><p>{{cong_ty}} trân trọng cảm ơn sự quan tâm, phối hợp của Quý cơ quan./.</p>"}, {"t": "sign", "html": "<b>Nơi nhận:</b><br>- Như trên;<br>- Hiệp hội Sầu riêng tỉnh Đắk Lắk;<br>- Lưu: VT, BVI."}]}'::jsonb,50 on conflict (code) do nothing;
insert into public.sales_templates(code,kind,name,description,company_id,body,sort) select 'tpl-cv-su-kien','letter','Công văn đề nghị phối hợp tổ chức sự kiện tập huấn TXNG, MSVT','Khi xã đồng ý làm sự kiện. Kèm chương trình 1 buổi và mẫu danh sách đăng ký.',(select id from public.sales_companies where code='bvi'),'{"title": "", "subtitle": "đề nghị phối hợp tổ chức chương trình đào tạo, tập huấn truy xuất nguồn gốc, mã số vùng trồng trên địa bàn {{xa}}", "to": "<p><b>Kính gửi:</b></p><p>- Ủy ban nhân dân {{xa}};</p><p>- Phòng Kinh tế {{xa}}.</p>", "blocks": [{"t": "text", "h": "", "html": "<ul><li>Căn cứ Luật Trồng trọt số 31/2018/QH14 ngày 19/11/2018;</li><li>Căn cứ Nghị định số 77/2019/NĐ-CP ngày 10/10/2019 của Chính phủ về tổ hợp tác;</li><li>Căn cứ Thông tư số 06/2021/TT-BNNPTNT ngày 08/7/2021 của Bộ Nông nghiệp và Phát triển nông thôn (nay là Bộ Nông nghiệp và Môi trường) quy định về xây dựng và quản lý vùng trồng;</li><li>Căn cứ Nghị quyết số 36/2026/NQ-CP của Chính phủ về đơn giản hóa thủ tục hành chính liên quan đến mã số vùng trồng, mã số cơ sở đóng gói;</li><li>Căn cứ Nghị định số 372/2026/NĐ-CP ngày 29/9/2026 của Chính phủ quy định về hoạt động định danh, xác thực, truy xuất nguồn gốc sản phẩm, hàng hóa;</li><li>Căn cứ Quyết định số 5272/QĐ-BNNMT ngày 13/12/2025 của Bộ Nông nghiệp và Môi trường ban hành Kế hoạch thí điểm truy xuất nguồn gốc quả sầu riêng và Công văn số 7812/BNNMT-KHCN ngày 15/7/2026 về triển khai Hệ thống truy xuất nguồn gốc nông sản;</li></ul><p>{{cong_ty}} (sau đây gọi là {{cong_ty_ngan}}), hội viên Hiệp hội Sầu riêng tỉnh Đắk Lắk, kính đề nghị Ủy ban nhân dân {{xa}} và Phòng Kinh tế {{xa}} (sau đây gọi chung là Quý cơ quan) phối hợp tập hợp các vùng trồng, hộ dân, hợp tác xã, tổ hợp tác và doanh nghiệp trên địa bàn tham gia chương trình đào tạo, tập huấn về truy xuất nguồn gốc, mã số vùng trồng và kỹ thuật sản xuất, tổ chức trong 01 buổi gồm ba phần chuyên đề, cụ thể như sau:</p>"}, {"t": "text", "h": "I. MỤC ĐÍCH, YÊU CẦU", "html": "<ul><li>Phổ biến quy định hiện hành về truy xuất nguồn gốc và mã số vùng trồng; hướng dẫn vùng trồng đã có mã thực hiện truy xuất nguồn gốc tích hợp với Hệ thống truy xuất nguồn gốc nông sản của Bộ Nông nghiệp và Môi trường (txng.mae.gov.vn), đáp ứng yêu cầu hậu kiểm và duy trì mã.</li><li>Giúp hộ dân có nhu cầu nắm rõ trình tự đăng ký mã số vùng trồng, cách thành lập tổ hợp tác để chủ động đứng tên mã, quyền và nghĩa vụ khi hậu kiểm, duy trì mã.</li><li>Cập nhật kiến thức thực hành sản xuất tốt, kiểm dịch thực vật, kỹ thuật canh tác, xử lý sau thu hoạch và quản lý hợp tác xã, tổ hợp tác.</li><li>Tổng hợp nhu cầu đăng ký sử dụng FarmBase và đăng ký hỗ trợ xây dựng mã số vùng trồng làm cơ sở thống nhất kế hoạch triển khai.</li><li>Áp dụng trước cho cây sầu riêng, có thể mở rộng cho cà phê và cây trồng xuất khẩu chủ lực khác; không làm phát sinh nghĩa vụ bắt buộc sử dụng dịch vụ của {{cong_ty_ngan}}.</li></ul>"}, {"t": "text", "h": "II. ĐỐI TƯỢNG THAM GIA", "html": "<p>1. Vùng trồng đã có mã số (mã GACC, mã nội địa): người đại diện vùng, hợp tác xã, tổ hợp tác, doanh nghiệp quản lý vùng, cán bộ kỹ thuật và nông hộ ghi nhật ký.</p><p>2. Hộ dân có nhu cầu đăng ký mã số vùng trồng, người dân muốn liên kết thành lập tổ hợp tác.</p><p>3. Đại biểu: lãnh đạo Ủy ban nhân dân xã, Phòng Kinh tế xã; Hiệp hội Sầu riêng tỉnh Đắk Lắk; đơn vị phối hợp, chuyên gia đối tác nông nghiệp; hợp tác xã, tổ hợp tác, doanh nghiệp thu mua, xuất khẩu trên địa bàn.</p>"}, {"t": "text", "h": "III. NỘI DUNG ĐÀO TẠO, TẬP HUẤN", "html": "<p><b>Phần 1 – Truy xuất nguồn gốc (vùng đã có mã):</b> Nghị định số 372/2026/NĐ-CP (hiệu lực từ 01/01/2027); hậu kiểm, duy trì mã: nhật ký canh tác, phân bón, thuốc bảo vệ thực vật đúng danh mục, thời gian cách ly, bẫy côn trùng, kho vật tư, hồ sơ thu hoạch, các trường hợp mã bị tạm dừng, thu hồi; hướng dẫn FarmBase (web cho hợp tác xã, Zalo Mini App cho nông dân); đăng ký dùng miễn phí 01 năm, tạo tài khoản tại chỗ.</p><p><b>Phần 2 – Mã số vùng trồng (hộ dân có nhu cầu):</b> lợi ích, quyền và nghĩa vụ; làm mã không ảnh hưởng quyền sử dụng đất, chủ vườn vẫn toàn quyền mua bán; điều kiện, hồ sơ, trình tự đăng ký mã nội địa theo Nghị quyết số 36/2026/NQ-CP (nộp tại Ủy ban nhân dân xã qua Cổng Dịch vụ công, xã kiểm tra trong 10 ngày làm việc) và các bước đề nghị cấp mã GACC; yêu cầu đất không tranh chấp, đất thuê phải có hồ sơ thuê; thành lập tổ hợp tác theo Nghị định số 77/2019/NĐ-CP; đăng ký nhận hỗ trợ xây dựng mã.</p><p><b>Phần 3 – Chuyên đề kỹ thuật và quản lý (tất cả các nhóm):</b> lựa chọn theo nhu cầu địa phương: VietGAP; ISPM 6 (giám sát sinh vật gây hại); kỹ thuật canh tác, xử lý sau thu hoạch; quản lý hợp tác xã, tổ hợp tác.</p>"}, {"t": "text", "h": "IV. THỜI GIAN, ĐỊA ĐIỂM, QUY MÔ DỰ KIẾN", "html": "<ul><li>Thời gian: [khoảng ngày đề xuất], trong 01 buổi (sáng hoặc chiều), khoảng 03 giờ; ngày cụ thể theo sắp xếp của Quý cơ quan.</li><li>Địa điểm: Hội trường Ủy ban nhân dân {{xa}} (hoặc địa điểm do Quý cơ quan bố trí).</li><li>Quy mô: khoảng [số người] người.</li></ul>"}, {"t": "text", "h": "V. PHÂN CÔNG THỰC HIỆN", "html": "<p><b>1. {{cong_ty}}:</b> chuẩn bị nội dung, tài liệu, giảng viên, trình chiếu; mời chuyên gia đối tác cho Phần 3; cung cấp mẫu danh sách đăng ký (Phụ lục 02); hỗ trợ tạo tài khoản FarmBase tại chỗ; tổng hợp kết quả gửi Quý cơ quan sau buổi tập huấn. Kinh phí hậu cần (nếu có) hai bên thống nhất trước khi tổ chức.</p><p><b>2. Kính đề nghị Quý cơ quan:</b> cử cán bộ đầu mối phối hợp; rà soát danh sách vùng trồng đã có mã GACC, mã nội địa và mời đại diện tham gia Phần 1; thông báo qua truyền thanh, các thôn, buôn để hộ dân đăng ký Phần 2, Phần 3; bố trí hội trường, âm thanh, máy chiếu; cử lãnh đạo, cán bộ tham dự.</p>"}, {"t": "text", "h": "VI. ĐĂNG KÝ VÀ LIÊN HỆ", "html": "<p>Kính đề nghị Quý cơ quan tổng hợp danh sách đăng ký theo Phụ lục 02 và gửi về {{cong_ty_ngan}} trước ngày [hạn gửi danh sách] để chuẩn bị tài liệu, tài khoản phù hợp số lượng tham dự.</p><p>Việc cấp, quản lý mã số vùng trồng thuộc thẩm quyền cơ quan quản lý nhà nước; {{cong_ty_ngan}} hỗ trợ kỹ thuật, hồ sơ và vận hành hệ thống, không cam kết thời gian cấp mã. Bà con tự nguyện tham gia, không phát sinh nghĩa vụ bắt buộc sử dụng dịch vụ của {{cong_ty_ngan}}; dữ liệu cá nhân được bảo mật theo Nghị định số 13/2023/NĐ-CP.</p><p>Đầu mối liên hệ: bà Ngọc, điện thoại/Zalo: {{dien_thoai}}; email: {{email}}. Cán bộ phụ trách: {{nguoi_lap}}. {{cong_ty_ngan}} kính đề nghị Quý cơ quan thông tin họ tên, chức vụ, số điện thoại cán bộ đầu mối để hai bên thống nhất kế hoạch chi tiết.</p><p>{{cong_ty}} trân trọng cảm ơn sự quan tâm, phối hợp của Quý cơ quan./.</p>"}, {"t": "sign", "html": "<b>Nơi nhận:</b><br>- Như trên;<br>- Hiệp hội Sầu riêng tỉnh Đắk Lắk;<br>- Lưu: VT, BVI."}, {"t": "text", "h": "PHỤ LỤC 01. CHƯƠNG TRÌNH DỰ KIẾN", "html": "<table><thead><tr><th>Thời gian</th><th>Nội dung</th><th>Phụ trách</th></tr></thead><tbody><tr><td>08h15 – 08h30</td><td>Đón tiếp đại biểu; đăng ký tham dự</td><td>{{cong_ty_ngan}}, UBND xã</td></tr><tr><td>08h30 – 08h45</td><td>Tuyên bố lý do, giới thiệu đại biểu; phát biểu chỉ đạo; phát biểu của Hiệp hội Sầu riêng tỉnh Đắk Lắk</td><td>UBND xã, Hiệp hội</td></tr><tr><td>08h45 – 09h05</td><td><b>Phần 1.</b> Quy định về truy xuất nguồn gốc; Hệ thống truy xuất nguồn gốc nông sản của Bộ Nông nghiệp và Môi trường</td><td>{{cong_ty_ngan}}</td></tr><tr><td>09h05 – 09h25</td><td>Hậu kiểm, duy trì mã số vùng trồng: nhật ký canh tác, phân bón, thuốc bảo vệ thực vật, thời gian cách ly, bẫy côn trùng, kho vật tư, hồ sơ thu hoạch</td><td>{{cong_ty_ngan}}, đơn vị phối hợp</td></tr><tr><td>09h25 – 09h45</td><td>Hướng dẫn sơ bộ ứng dụng FarmBase; đăng ký sử dụng miễn phí 01 năm cho vùng đã có mã (không gồm chi phí thực địa phát sinh, nếu có)</td><td>{{cong_ty_ngan}}</td></tr><tr><td>09h45 – 10h05</td><td><b>Phần 2.</b> Mã số vùng trồng: lợi ích, quyền và nghĩa vụ; điều kiện, hồ sơ, trình tự đăng ký mã nội địa và mã GACC</td><td>{{cong_ty_ngan}}</td></tr><tr><td>10h05 – 10h25</td><td>Thành lập tổ hợp tác để chủ động đứng tên mã số vùng trồng; đăng ký, hậu kiểm, duy trì mã; đăng ký nhận hỗ trợ</td><td>{{cong_ty_ngan}}, đơn vị phối hợp</td></tr><tr><td>10h25 – 11h05</td><td><b>Phần 3.</b> Chuyên đề lựa chọn: VietGAP; ISPM 6; kỹ thuật canh tác, xử lý sau thu hoạch; hoặc quản lý hợp tác xã, tổ hợp tác</td><td>Chuyên gia đối tác</td></tr><tr><td>11h05 – 11h30</td><td>Trao đổi, giải đáp; hỗ trợ đăng ký tại chỗ; tổng kết, bế mạc</td><td>{{cong_ty_ngan}}, UBND xã</td></tr></tbody></table><p><i>Thời gian, nội dung và chuyên đề Phần 3 có thể điều chỉnh theo đề nghị của Quý cơ quan.</i></p>"}, {"t": "text", "h": "PHỤ LỤC 02. MẪU DANH SÁCH ĐĂNG KÝ THAM GIA", "html": "<p><b>A. Vùng trồng đã có mã số (tham gia Phần 1 và Phần 3)</b></p><table><thead><tr><th>TT</th><th>Tên vùng trồng, chủ thể quản lý</th><th>Mã số vùng trồng</th><th>Loại mã (GACC, nội địa)</th><th>Cây trồng, diện tích (ha), số hộ</th><th>Người đại diện, điện thoại</th><th>Đăng ký FarmBase miễn phí 01 năm</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><b>B. Hộ dân có nhu cầu đăng ký mã số vùng trồng (tham gia Phần 2 và Phần 3)</b></p><table><thead><tr><th>TT</th><th>Họ và tên</th><th>Thôn, buôn</th><th>Cây trồng</th><th>Diện tích (ha)</th><th>Nhu cầu (tìm hiểu, lập tổ hợp tác, đăng ký hỗ trợ làm mã)</th><th>Điện thoại</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><i>Thông tin cá nhân trong danh sách chỉ dùng để tổ chức tập huấn và hỗ trợ đăng ký; {{cong_ty_ngan}} bảo mật theo quy định về bảo vệ dữ liệu cá nhân.</i></p>"}]}'::jsonb,60 on conflict (code) do nothing;
insert into public.sales_templates(code,kind,name,description,company_id,body,sort) select 'tpl-cv-trien-khai','letter','Công văn đề nghị phối hợp triển khai TXNG, tập huấn theo thôn, buôn','Sau buổi làm việc hoặc hội nghị: triển khai rộng theo thôn, buôn.',(select id from public.sales_companies where code='bvi'),'{"title": "", "subtitle": "đề nghị phối hợp, kết nối các thôn, buôn tổ chức tập huấn, hướng dẫn nông dân đăng ký, hậu kiểm, duy trì mã số vùng trồng và ứng dụng truy xuất nguồn gốc trên địa bàn {{xa}}", "to": "<p><b>Kính gửi:</b></p><p>- Ủy ban nhân dân {{xa}};</p><p>- Phòng Kinh tế {{xa}}.</p>", "blocks": [{"t": "text", "h": "", "html": "<ul><li>Căn cứ Luật Trồng trọt số 31/2018/QH14 ngày 19/11/2018;</li><li>Căn cứ Nghị định số 77/2019/NĐ-CP ngày 10/10/2019 của Chính phủ về tổ hợp tác;</li><li>Căn cứ Thông tư số 06/2021/TT-BNNPTNT ngày 08/7/2021 của Bộ Nông nghiệp và Phát triển nông thôn (nay là Bộ Nông nghiệp và Môi trường) quy định về xây dựng và quản lý vùng trồng;</li><li>Căn cứ Nghị quyết số 36/2026/NQ-CP của Chính phủ về đơn giản hóa thủ tục hành chính liên quan đến mã số vùng trồng, mã số cơ sở đóng gói;</li><li>Căn cứ Nghị định số 372/2026/NĐ-CP ngày 29/9/2026 của Chính phủ quy định về hoạt động định danh, xác thực, truy xuất nguồn gốc sản phẩm, hàng hóa;</li><li>Căn cứ Quyết định số 5272/QĐ-BNNMT ngày 13/12/2025 của Bộ Nông nghiệp và Môi trường ban hành Kế hoạch thí điểm truy xuất nguồn gốc quả sầu riêng và Công văn số 7812/BNNMT-KHCN ngày 15/7/2026 về triển khai Hệ thống truy xuất nguồn gốc nông sản;</li></ul><p>{{cong_ty}} (sau đây gọi là {{cong_ty_ngan}}), hội viên Hiệp hội Sầu riêng tỉnh Đắk Lắk, là đơn vị phát triển và vận hành nền tảng FarmBase phục vụ quản lý vùng trồng, nhật ký canh tác điện tử và truy xuất nguồn gốc. Nhằm giúp bà con chủ động đăng ký, hậu kiểm, duy trì mã số vùng trồng và sẵn sàng đáp ứng yêu cầu truy xuất nguồn gốc khi Nghị định số 372/2026/NĐ-CP có hiệu lực từ ngày 01/01/2027, {{cong_ty_ngan}} kính đề nghị Ủy ban nhân dân {{xa}} giao Phòng Kinh tế (sau đây gọi chung là Quý cơ quan) phối hợp triển khai chương trình, kết nối các thôn, buôn để tổ chức tập huấn tại chỗ, cụ thể như sau:</p>"}, {"t": "text", "h": "I. MỤC ĐÍCH, YÊU CẦU", "html": "<ul><li>Giúp nông dân, tổ hợp tác, hợp tác xã nắm rõ điều kiện, hồ sơ, trình tự để chủ động đứng tên đăng ký mã số vùng trồng; tự thực hiện hậu kiểm, duy trì mã, hạn chế phụ thuộc đơn vị trung gian.</li><li>Tập huấn theo từng thôn, buôn hoặc cụm thôn, buôn; bà con tự chọn hình thức đứng mã: (1) liên kết các hộ liền vùng thành lập tổ hợp tác; hoặc (2) liên kết với hợp tác xã phù hợp trên địa bàn. Việc lựa chọn hoàn toàn do bà con quyết định.</li><li>Hướng dẫn ghi nhật ký canh tác điện tử, truy xuất nguồn gốc trên FarmBase, liên thông Hệ thống truy xuất nguồn gốc nông sản của Bộ Nông nghiệp và Môi trường và định danh sản phẩm theo chuẩn GS1.</li><li>Bàn giao, hướng dẫn tài khoản giám sát truy xuất nguồn gốc cấp xã, hỗ trợ Quý cơ quan kiểm tra, hậu kiểm mã số vùng trồng theo Nghị quyết số 36/2026/NQ-CP.</li><li>Áp dụng trước cho cây sầu riêng, có thể mở rộng cho cà phê và cây trồng xuất khẩu chủ lực khác. Không thay thế thẩm quyền của cơ quan nhà nước trong cấp, quản lý mã số vùng trồng.</li></ul>"}, {"t": "text", "h": "II. NỘI DUNG CHƯƠNG TRÌNH", "html": "<p><b>1. Hướng dẫn nông dân chủ động với mã số vùng trồng:</b> a) Đăng ký: lợi ích, quyền và nghĩa vụ (không ảnh hưởng quyền sử dụng đất, chủ vườn vẫn toàn quyền mua bán); điều kiện, hồ sơ, trình tự đăng ký mã nội địa theo Nghị quyết số 36/2026/NQ-CP và các bước đề nghị mã xuất khẩu; hai hình thức đứng mã. b) Hậu kiểm: hồ sơ, hiện trường trước kiểm tra; nhật ký; phân bón, thuốc đúng danh mục, thời gian cách ly; bẫy côn trùng; kho vật tư; hồ sơ thu hoạch, tiêu thụ. c) Duy trì: trách nhiệm người đại diện và thành viên; cập nhật thay đổi diện tích, chủ hộ, giống; lịch giám sát hằng năm; nhận diện sớm sai phạm có nguy cơ bị tạm dừng, thu hồi mã.</p><p><b>2. Hướng dẫn truy xuất nguồn gốc FarmBase:</b> nông dân ghi nhật ký, lưu ảnh bao bì vật tư, cập nhật thu hoạch qua Zalo Mini App; hợp tác xã, tổ hợp tác quản lý trên web; dữ liệu đồng bộ lên hệ thống của Bộ Nông nghiệp và Môi trường (txng.mae.gov.vn) theo nguyên tắc ghi một lần, dùng nhiều mục đích; hỗ trợ định danh sản phẩm, lô hàng, tem QR theo chuẩn GS1; phổ biến Nghị định số 372/2026/NĐ-CP; hướng dẫn cán bộ Phòng Kinh tế dùng tài khoản giám sát.</p><p><b>3. Hình thức:</b> hội nghị triển khai tại xã; tập huấn tại thôn, buôn (khoảng 03 giờ mỗi buổi, chương trình tại Phụ lục 01); tổng hợp nhu cầu theo Phụ lục 02; hỗ trợ lập tổ hợp tác hoặc kết nối hợp tác xã, hoàn thiện hồ sơ nộp Ủy ban nhân dân xã; hướng dẫn tại vườn; hỗ trợ qua Zalo, điện thoại.</p>"}, {"t": "text", "h": "III. KINH PHÍ", "html": "<ul><li>Chương trình không đề nghị sử dụng ngân sách nhà nước.</li><li>Tài khoản giám sát cấp xã miễn phí; hướng dẫn truy xuất nguồn gốc cho nông hộ miễn phí đến hết ngày 31/12/2026; vùng đã có mã dùng FarmBase miễn phí năm đầu (không gồm chi phí thực địa phát sinh, nếu có).</li><li>Tổ hợp tác, hợp tác xã đề nghị {{cong_ty_ngan}} hỗ trợ xây dựng hồ sơ mã số vùng trồng mới: chi phí công khai, thỏa thuận trước, tinh gọn để hỗ trợ người dân.</li><li>Người dân, tổ chức tham gia là chủ sở hữu dữ liệu; dữ liệu cá nhân được bảo mật theo Nghị định số 13/2023/NĐ-CP.</li></ul>"}, {"t": "text", "h": "IV. PHÂN CÔNG THỰC HIỆN", "html": "<p><b>1. {{cong_ty}}:</b> chuẩn bị nội dung, tài liệu, giảng viên; phối hợp trưởng thôn, buôn tổ chức tập huấn; tổng hợp nhu cầu, tư vấn hình thức đứng mã; hướng dẫn cán bộ Phòng Kinh tế dùng tài khoản giám sát; báo cáo kết quả định kỳ hằng quý.</p><p><b>2. Kính đề nghị Ủy ban nhân dân {{xa}}:</b> cho chủ trương triển khai; giao Phòng Kinh tế làm đầu mối; chỉ đạo trưởng thôn, buôn, chi hội nông dân thông báo, tổng hợp nhu cầu, bố trí nhà văn hóa; giới thiệu hợp tác xã hoạt động hiệu quả để bà con liên kết.</p><p><b>3. Kính đề nghị Phòng Kinh tế {{xa}}:</b> cử cán bộ đầu mối; cung cấp danh sách vùng trồng đã có mã, đang đề nghị cấp mã, danh sách hợp tác xã, tổ hợp tác; thống nhất lịch tập huấn với các thôn, buôn; cử cán bộ tham dự.</p>"}, {"t": "text", "h": "V. THỜI GIAN DỰ KIẾN", "html": "<ul><li>[Tháng triển khai]: làm việc thống nhất kế hoạch; rà soát danh sách vùng trồng; hội nghị triển khai tại xã và lập lịch tập huấn theo thôn, buôn.</li><li>Tập huấn lần lượt tại các thôn, buôn có nhu cầu; hướng dẫn tại vườn; hỗ trợ lập tổ hợp tác hoặc liên kết hợp tác xã; hỗ trợ áp dụng truy xuất nguồn gốc theo Nghị định số 372/2026/NĐ-CP.</li></ul><p>Việc cấp, quản lý mã số vùng trồng thuộc thẩm quyền cơ quan quản lý nhà nước; {{cong_ty_ngan}} hỗ trợ kỹ thuật, hồ sơ và vận hành hệ thống, không cam kết thời gian cấp mã. Bà con tự nguyện tham gia, không phát sinh nghĩa vụ bắt buộc sử dụng dịch vụ của {{cong_ty_ngan}}; dữ liệu cá nhân được bảo mật theo Nghị định số 13/2023/NĐ-CP.</p><p>Đầu mối liên hệ: bà Ngọc, điện thoại/Zalo: {{dien_thoai}}; email: {{email}}. Cán bộ phụ trách: {{nguoi_lap}}. {{cong_ty_ngan}} kính đề nghị Quý cơ quan thông tin họ tên, chức vụ, số điện thoại cán bộ đầu mối để hai bên thống nhất kế hoạch chi tiết.</p><p>{{cong_ty}} trân trọng cảm ơn sự quan tâm, phối hợp của Quý cơ quan./.</p>"}, {"t": "sign", "html": "<b>Nơi nhận:</b><br>- Như trên;<br>- Hiệp hội Sầu riêng tỉnh Đắk Lắk;<br>- Lưu: VT, BVI."}, {"t": "text", "h": "PHỤ LỤC 01. CHƯƠNG TRÌNH DỰ KIẾN BUỔI TẬP HUẤN TẠI THÔN, BUÔN", "html": "<table><thead><tr><th>Thời gian</th><th>Nội dung</th><th>Thực hiện</th></tr></thead><tbody><tr><td>08h00 – 08h15</td><td>Đón tiếp; đăng ký tham dự</td><td>{{cong_ty_ngan}}, thôn, buôn</td></tr><tr><td>08h15 – 08h25</td><td>Khai mạc, giới thiệu chương trình</td><td>Phòng Kinh tế, trưởng thôn, buôn</td></tr><tr><td>08h25 – 09h05</td><td>Mã số vùng trồng: lợi ích, quyền và nghĩa vụ; điều kiện, hồ sơ, trình tự đăng ký</td><td>{{cong_ty_ngan}}</td></tr><tr><td>09h05 – 09h30</td><td>Hai hình thức đứng mã: thành lập tổ hợp tác để chủ động đứng tên, hoặc liên kết hợp tác xã phù hợp</td><td>{{cong_ty_ngan}}, Phòng Kinh tế, đại diện HTX</td></tr><tr><td>09h30 – 10h05</td><td>Hậu kiểm và duy trì mã: nhật ký canh tác, phân bón, thuốc bảo vệ thực vật, thời gian cách ly, bẫy côn trùng, kho vật tư, hồ sơ thu hoạch</td><td>{{cong_ty_ngan}}</td></tr><tr><td>10h05 – 10h40</td><td>Nghị định số 372/2026/NĐ-CP; truy xuất nguồn gốc trên FarmBase, liên thông hệ thống của Bộ Nông nghiệp và Môi trường, định danh GS1</td><td>{{cong_ty_ngan}}</td></tr><tr><td>10h40 – 11h10</td><td>Thực hành: cài Zalo Mini App, ghi nhật ký mẫu; hướng dẫn cán bộ xã dùng tài khoản giám sát</td><td>{{cong_ty_ngan}}</td></tr><tr><td>11h10 – 11h30</td><td>Trao đổi, giải đáp; đăng ký nhu cầu theo Phụ lục 02; bế mạc</td><td>{{cong_ty_ngan}}, thôn, buôn</td></tr></tbody></table>"}, {"t": "text", "h": "PHỤ LỤC 02. MẪU TỔNG HỢP NHU CẦU THEO THÔN, BUÔN", "html": "<table><thead><tr><th>TT</th><th>Thôn, buôn</th><th>Số hộ có nhu cầu</th><th>Cây trồng</th><th>Diện tích dự kiến (ha)</th><th>Hình thức (tự lập THT, liên kết HTX, chưa chọn)</th><th>Thời gian tập huấn mong muốn</th><th>Người liên hệ</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><i>Phòng Kinh tế phối hợp trưởng thôn, buôn tổng hợp và gửi {{cong_ty_ngan}} để bố trí lịch. Danh sách hộ chi tiết do thôn, buôn quản lý.</i></p>"}]}'::jsonb,70 on conflict (code) do nothing;
insert into public.sales_templates(code,kind,name,description,company_id,body,sort) select 'tpl-hd-mvt-nong-dan','letter','Tài liệu hướng dẫn bà con làm mã số vùng trồng','Phát cho bà con tại buổi tập huấn hoặc gửi xã in, chia sẻ Zalo.',(select id from public.sales_companies where code='bvi'),'{"layout": "doc", "title": "HƯỚNG DẪN BÀ CON LÀM MÃ SỐ VÙNG TRỒNG", "subtitle": "Tài liệu phát cho bà con tại {{xa}} · Áp dụng trước cho cây sầu riêng, có thể dùng cho cà phê và cây xuất khẩu khác", "blocks": [{"t": "text", "h": "1. Mã số vùng trồng là gì, có lợi gì", "html": "<p>Mã số vùng trồng là mã định danh cho một vùng trồng một loại cây, gắn với các thửa đất và nhóm hộ đã đăng ký. Với sầu riêng xuất khẩu chính ngạch sang Trung Quốc, chỉ trái từ vùng có mã được phía Trung Quốc (GACC) phê duyệt và đi qua cơ sở đóng gói có mã mới được xuất.</p><ul><li>Bán được cho doanh nghiệp xuất khẩu chính ngạch, giá ổn định hơn.</li><li>Làm mã <b>không ảnh hưởng quyền sử dụng đất</b>; chủ vườn vẫn toàn quyền quyết định bán cho ai.</li><li>Từ ngày 01/01/2027 (Nghị định số 372/2026/NĐ-CP), sản phẩm cần truy xuất được nguồn gốc; có mã và nhật ký giúp bà con sẵn sàng.</li></ul>"}, {"t": "text", "h": "2. Điều kiện tham gia", "html": "<ul><li>Diện tích: Nghị quyết số 36/2026/NQ-CP đã bỏ yêu cầu diện tích tối thiểu. {{cong_ty_ngan}} khuyến nghị khoảng 10 ha mỗi mã để chi phí trên mỗi ha thấp (không bắt buộc); vùng nhỏ nên gộp các hộ, vườn liền kề.</li><li>Đất rõ ràng: không đang tranh chấp. Đất thuê, mượn phải có hợp đồng thuê còn hiệu lực, ghi rõ thửa, thời hạn, chủ đất đồng ý. Lô không đủ giấy tờ để ngoài vùng.</li><li>Có đơn vị đứng tên: tổ hợp tác hoặc hợp tác xã, có người đại diện vùng.</li><li>Cam kết ghi nhật ký canh tác, chỉ dùng thuốc bảo vệ thực vật được phép, không đưa trái ngoài vùng vào bán chung mã.</li></ul>"}, {"t": "text", "h": "3. Ai đứng tên mã", "html": "<p>Bà con tự chọn, không ai được ép:</p><ul><li><b>Tự lập tổ hợp tác</b> với các hộ liền vùng theo Nghị định số 77/2019/NĐ-CP: ký hợp đồng hợp tác, bầu người đại diện, bà con chủ động quản lý mã.</li><li><b>Liên kết hợp tác xã</b> phù hợp trên địa bàn: hợp tác xã đứng tên, bà con là thành viên hoặc hộ liên kết; thỏa thuận rõ quyền lợi, giá, tiêu chuẩn, thời điểm thu mua.</li></ul>"}, {"t": "text", "h": "4. Giấy tờ cần chuẩn bị", "html": "<ul><li>Căn cước công dân của chủ hộ (bản chụp, chỉ dùng cho hồ sơ mã, được bảo mật).</li><li>Giấy chứng nhận quyền sử dụng đất (sổ đỏ) hoặc số tờ, số thửa; đất thuê kèm hợp đồng thuê.</li><li>Thông tin vườn: diện tích, số cây, giống, năm trồng, sản lượng dự kiến.</li><li>Danh sách hộ tham gia, có chữ ký.</li><li>Hợp đồng hợp tác của tổ hợp tác hoặc giấy xác nhận là thành viên hợp tác xã.</li></ul>"}, {"t": "text", "h": "5. Các bước làm mã", "html": "<table><thead><tr><th>Bước</th><th>Việc cần làm</th><th>Ai làm</th></tr></thead><tbody><tr><td>1</td><td>Họp dân, khảo sát vườn, chọn hộ và đơn vị đứng tên</td><td>Bà con, {{cong_ty_ngan}}</td></tr><tr><td>2</td><td>Thu giấy tờ, lập tổ hợp tác hoặc liên kết hợp tác xã</td><td>Bà con, đại diện vùng</td></tr><tr><td>3</td><td>Đo ranh, lấy tọa độ, chụp flycam, lập bản đồ từng lô</td><td>{{cong_ty_ngan}}</td></tr><tr><td>4</td><td>Treo biển vùng, đặt bẫy côn trùng, sắp xếp kho thuốc; tập huấn ghi nhật ký</td><td>Bà con, {{cong_ty_ngan}}</td></tr><tr><td>5</td><td>Ghi nhật ký phân bón, thuốc, sâu bệnh, thu hoạch trên Zalo FarmBase</td><td>Từng hộ</td></tr><tr><td>6</td><td>Nộp hồ sơ tại Ủy ban nhân dân xã qua Cổng Dịch vụ công; xã kiểm tra thực địa trong 10 ngày làm việc</td><td>Đại diện vùng, UBND xã</td></tr><tr><td>7</td><td>Tỉnh, Bộ gửi danh sách sang nước nhập khẩu; chỉ xuất khẩu được từ ngày phía Trung Quốc phê duyệt</td><td>Cơ quan nhà nước</td></tr></tbody></table>"}, {"t": "text", "h": "6. Sau khi có mã: giữ mã thế nào", "html": "<ul><li>Ghi nhật ký đều đặn cả vụ, không ghi dồn.</li><li>Dùng thuốc đúng danh mục, đúng liều, đủ thời gian cách ly; giữ vỏ bao bì, hóa đơn.</li><li>Kiểm tra bẫy côn trùng định kỳ; báo ngay khi có sâu bệnh lạ.</li><li>Báo đại diện vùng khi thay đổi diện tích, chủ hộ, giống.</li><li>Sẵn sàng hồ sơ và hiện trường khi đoàn hậu kiểm đến. Vi phạm có thể bị tạm dừng hoặc thu hồi mã.</li></ul>"}, {"t": "text", "h": "7. Chi phí tham khảo", "html": "<p>Tính cho một vùng trồng do tổ hợp tác, hợp tác xã của bà con đứng tên, từ khi lập hồ sơ đến khi được cấp mã; chỉ gồm các khoản thực tế phải chi, công khai trước khi triển khai:</p><ul><li>Đợt 1, khi triển khai: 15.000.000 đồng/vùng, gồm đi lại và công tác phí chuyên gia thực địa (03 ngày, vùng cách dưới 30 km), in ấn hồ sơ, chụp flycam, vật tư (bẫy côn trùng, biển thông tin vùng, bảo hộ), thù lao người đại diện vùng và hậu cần đợt kiểm tra thực địa;</li><li>Đợt 2, chỉ khi vùng được cấp mã: 5.000.000 đồng/vùng (phí hoàn thiện hồ sơ); vùng chưa được cấp mã không phải trả khoản này.</li></ul><p>Tổng khoảng 20.000.000 đồng/vùng, tương đương khoảng 2.000.000 đồng/ha với vùng 10 ha. Chưa gồm chi phí duy trì, hậu kiểm mã số vùng trồng hằng năm sau khi được cấp mã, lệ phí nhà nước và dịch vụ của bên thứ ba (nếu có). Ngày thực địa phát sinh tính thêm theo thực tế.</p><p>Bà con có thể tự làm theo hướng dẫn tại xã. Việc cấp mã thuộc cơ quan nhà nước và nước nhập khẩu; {{cong_ty_ngan}} hỗ trợ kỹ thuật, hồ sơ, không cam kết thời gian cấp mã.</p>"}, {"t": "text", "h": "8. Liên hệ", "html": "<p>Đăng ký tập huấn, hỗ trợ: bà Ngọc, điện thoại/Zalo {{dien_thoai}}; email {{email}}. Hoặc liên hệ Phòng Kinh tế {{xa}}.</p>"}]}'::jsonb,80 on conflict (code) do nothing;

commit;
